#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
ضاغط فيديوهات وتر (Watar Video Compressor) - إصدار دفعات متعددة
------------------------------------------------------------------
برنامج لويندوز (واجهة رسومية) يصغّر مجموعة فيديوهات دفعة واحدة
(ملفات تختارها، أو مجلد كامل بالكامل)، باستخدام أكفأ طريقة ترميز
متاحة: AV1 أو HEVC عبر كرت شاشة NVIDIA (NVENC) إذا توفر، وإلا
HEVC/H.264 بالمعالج (برمجياً).

عندك طريقتان للعمل:

  أ) "جودة عالية تلقائياً" (موصى بها، وهذا اللي بيحقق طلبك: جودة
     عالية بأصغر حجم ممكن) - بتعتمد على CRF/CQ: تحدد مستوى الجودة
     المطلوب، والمرمّز بيستخدم أقل عدد بتات يحقق هذه الجودة، فالحجم
     الناتج يصغر تلقائياً بدون استهداف عدد ميجابايت معيّن.

  ب) "حجم ملف محدد" - تحدد حجماً نهائياً بالميجابايت (الطريقة
     القديمة) إذا كنت مُلزم بحد أقصى صارم (مثلاً للإيميل أو منصة
     معينة)، وتتنازل عن الجودة حسب الحاجة للوصول لهذا الحجم.

المتطلبات (تُثبَّت مرة واحدة فقط):
  1. Python 3.9+   من python.org  (فعّل "Add python.exe to PATH" عند التثبيت)
  2. FFmpeg (يتضمن ffprobe)   من gyan.dev/ffmpeg/builds  (نسخة "release essentials")
     - ضع ffmpeg.exe و ffprobe.exe بجانب هذا الملف، أو أضف مجلد bin لـ PATH

التشغيل:
  python compress_video.py
"""

import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import threading

AUDIO_KBPS_DEFAULT = 320  # جودة صوت عالية (320kbps) - ما تنزل الجودة حتى لو صغّرنا الفيديو كثير
SAFETY_MARGIN = 0.97  # لطريقة "حجم محدد": نهدف لحجم أقل بقليل من المستهدف كهامش أمان

VIDEO_EXTENSIONS = {".mp4", ".mkv", ".mov", ".avi", ".ts", ".m4v", ".wmv", ".flv", ".webm"}

# مستويات جودة تقريبية (CRF للمرمّزات البرمجية، CQ لمرمّزات NVENC).
# أرقام بداية منطقية؛ شاهد النتيجة وعدّل عبر "تجاوز يدوي" إذا احتجت.
QUALITY_PRESETS = {
    "libx265":     {"high": 18, "balanced": 21, "smaller": 24},
    "libx264":     {"high": 16, "balanced": 19, "smaller": 22},
    "hevc_nvenc":  {"high": 19, "balanced": 23, "smaller": 27},
    "av1_nvenc":   {"high": 22, "balanced": 27, "smaller": 32},
}

QUALITY_LEVEL_LABELS = {
    "high": "أعلى جودة (حجم أكبر نسبياً)",
    "balanced": "متوازن - موصى به",
    "smaller": "أصغر حجم (جودة جيدة جداً بس أوضح انضغاط)",
}

# تنعيم ضوضاء الكاميرا (grain/sensor noise) قبل الترميز. هذه نفس الحيلة التي
# تستخدمها منصات التواصل ومحطات البث لتصغر الحجم بدون أي تأثير يُذكر على
# الجودة المرئية - لأن الضوضاء العشوائية مكلفة جداً بالبتات وما تحمل تفاصيل
# حقيقية، فإزالتها الخفيفة تفرّغ بتات تروح لتفاصيل الصورة الحقيقية بدلاً منها.
DENOISE_FILTERS = {
    "off": None,
    "light": "hqdn3d=2:1.5:4:3",
    "medium": "hqdn3d=4:3:6:4.5",
}

DENOISE_LEVEL_LABELS = {
    "off": "إيقاف",
    "light": "خفيف - موصى به (يصغّر الحجم إضافياً بدون فرق يُذكر)",
    "medium": "متوسط (يصغّر أكثر، راقب فقدان تفاصيل دقيقة جداً)",
}

# شعار واتار برودكشن - مضمّن داخل الملف نفسه (base64) حتى يبقى البرنامج
# ملفاً واحداً محمولاً بدون أي صور أو موارد خارجية منفصلة.
LOGO_HEADER_PNG_B64 = (
    ""
)
LOGO_ICON_PNG_B64 = (
    ""
)


def find_tool(name):
    """
    يبحث عن الأداة بهذا الترتيب:
    ١. داخل الملف التنفيذي المجمّع نفسه (لما البرنامج يكون exe واحد مبني
       بـPyInstaller ومعه ffmpeg/ffprobe مدمجين) - عبر sys._MEIPASS.
    ٢. بجانب هذا الملف (وضع السكربت العادي compress_video.py).
    ٣. أخيراً في PATH.
    """
    search_dirs = []
    if getattr(sys, "frozen", False):
        search_dirs.append(getattr(sys, "_MEIPASS", os.path.dirname(sys.executable)))
        search_dirs.append(os.path.dirname(sys.executable))
    try:
        search_dirs.append(os.path.dirname(os.path.abspath(__file__)))
    except NameError:
        pass
    for d in search_dirs:
        candidate = os.path.join(d, name)
        if os.path.isfile(candidate):
            return candidate
    return shutil.which(name)


FFMPEG = find_tool("ffmpeg.exe") or find_tool("ffmpeg")
FFPROBE = find_tool("ffprobe.exe") or find_tool("ffprobe")


# ---------------------------------------------------------------------------
# فحص الملفات
# ---------------------------------------------------------------------------

def get_duration_seconds(path):
    cmd = [FFPROBE, "-v", "error", "-show_entries", "format=duration",
           "-of", "json", path]
    out = subprocess.run(cmd, capture_output=True, text=True, check=True)
    data = json.loads(out.stdout)
    return float(data["format"]["duration"])


def get_resolution(path):
    cmd = [FFPROBE, "-v", "error", "-select_streams", "v:0",
           "-show_entries", "stream=width,height", "-of", "json", path]
    out = subprocess.run(cmd, capture_output=True, text=True, check=True)
    streams = json.loads(out.stdout).get("streams", [])
    if not streams:
        return None
    return streams[0].get("width"), streams[0].get("height")


def is_4k_or_above(path):
    try:
        res = get_resolution(path)
        if not res:
            return True  # غير معروف: نفترض 4K للحيطة
        w, h = res
        return (w or 0) >= 3800 or (h or 0) >= 2100
    except Exception:
        return True


def available_encoders():
    out = subprocess.run([FFMPEG, "-hide_banner", "-encoders"],
                          capture_output=True, text=True)
    text = out.stdout
    return {
        "av1_nvenc": "av1_nvenc" in text,
        "hevc_nvenc": "hevc_nvenc" in text,
        "libx265": "libx265" in text,
        "libx264": "libx264" in text,
    }


def scan_folder_for_videos(folder):
    found = []
    for root, _dirs, files in os.walk(folder):
        for name in files:
            if os.path.splitext(name)[1].lower() in VIDEO_EXTENSIONS:
                found.append(os.path.join(root, name))
    return sorted(found)


# ---------------------------------------------------------------------------
# طريقة "حجم ملف محدد" (بتريت مُحسوب + ترميز بمرحلتين للمرمّزات البرمجية)
# ---------------------------------------------------------------------------

def compute_video_kbps(target_mb, duration_seconds, audio_kbps=AUDIO_KBPS_DEFAULT):
    if duration_seconds <= 0:
        raise ValueError("مدة الفيديو غير صحيحة")
    total_kbit = target_mb * 8000 * SAFETY_MARGIN
    total_kbps = total_kbit / duration_seconds
    return total_kbps - audio_kbps


def quality_floor_kbps(is_4k):
    return 1500 if is_4k else 600


def null_output():
    return "NUL" if os.name == "nt" else os.devnull


def _vf_args(vf):
    return ["-vf", vf] if vf else []


def build_nvenc_bitrate_cmd(path, out_path, codec, video_kbps, audio_kbps, vf=None):
    v_bitrate = f"{int(video_kbps)}k"
    maxrate = f"{int(video_kbps * 1.5)}k"
    bufsize = f"{int(video_kbps * 2)}k"
    return [
        FFMPEG, "-y", "-i", path,
        "-c:v", codec, "-preset", "p7", "-rc", "vbr",
        "-b:v", v_bitrate, "-maxrate", maxrate, "-bufsize", bufsize,
        *_vf_args(vf),
        "-c:a", "aac", "-b:a", f"{audio_kbps}k",
        out_path,
    ]


def build_x26x_2pass_cmds(path, out_path, codec, video_kbps, audio_kbps, vf=None):
    # preset "slow": نفس مستوى الجودة المستخدم بوضع "جودة عالية تلقائياً"، حتى
    # نستخرج أعلى جودة ممكنة من نفس عدد البتات المستهدف، بدل الإعداد الافتراضي
    # "medium" (أسرع لكن أضعف كفاءة ضغط بنفس البتريت).
    v_bitrate = f"{int(video_kbps)}k"
    null_out = null_output()
    if codec == "libx265":
        pass1 = [FFMPEG, "-y", "-i", path, "-c:v", "libx265", "-preset", "slow", "-b:v", v_bitrate,
                 *_vf_args(vf), "-x265-params", "pass=1", "-an", "-f", "mp4", null_out]
        pass2 = [FFMPEG, "-y", "-i", path, "-c:v", "libx265", "-preset", "slow", "-b:v", v_bitrate,
                 *_vf_args(vf), "-x265-params", "pass=2", "-c:a", "aac", "-b:a", f"{audio_kbps}k", out_path]
    else:  # libx264
        pass1 = [FFMPEG, "-y", "-i", path, "-c:v", "libx264", "-preset", "slow", "-b:v", v_bitrate,
                 *_vf_args(vf), "-pass", "1", "-an", "-f", "mp4", null_out]
        pass2 = [FFMPEG, "-y", "-i", path, "-c:v", "libx264", "-preset", "slow", "-b:v", v_bitrate,
                 *_vf_args(vf), "-pass", "2", "-c:a", "aac", "-b:a", f"{audio_kbps}k", out_path]
    return pass1, pass2


def compress_target_size(path, out_path, target_mb, encoder_key, log, audio_kbps=AUDIO_KBPS_DEFAULT,
                          denoise_level="off"):
    duration = get_duration_seconds(path)
    four_k = is_4k_or_above(path)
    video_kbps = compute_video_kbps(target_mb, duration, audio_kbps)

    floor = quality_floor_kbps(four_k)
    if video_kbps < floor:
        log(f"  تحذير: بترتيت الفيديو المحسوب ~{video_kbps:.0f} كيلوبت/ث منخفض جداً "
            f"({'4K' if four_k else 'لهذا الحجم'}؛ الحد الأدنى المعقول ~{floor}). "
            f"ستظهر عيوب ضغط واضحة عند هذا الحجم المستهدف.")
    video_kbps = max(video_kbps, 150)
    vf = DENOISE_FILTERS.get(denoise_level)

    if encoder_key in ("av1_nvenc", "hevc_nvenc"):
        log(f"  الترميز بواسطة {encoder_key} (كرت الشاشة) لحجم مستهدف...")
        run_checked(build_nvenc_bitrate_cmd(path, out_path, encoder_key, video_kbps, audio_kbps, vf), log)
    elif encoder_key in ("libx265", "libx264"):
        log(f"  الترميز بالمعالج ({encoder_key}، مرحلتين) لحجم مستهدف...")
        pass1, pass2 = build_x26x_2pass_cmds(path, out_path, encoder_key, video_kbps, audio_kbps, vf)
        run_checked(pass1, log)
        run_checked(pass2, log)
    else:
        raise ValueError(f"ترميز غير معروف: {encoder_key}")


# ---------------------------------------------------------------------------
# طريقة "جودة عالية تلقائياً" (CRF/CQ - موصى بها)
# ---------------------------------------------------------------------------

def build_quality_cmd(path, out_path, encoder_key, quality_value, audio_kbps, vf=None):
    if encoder_key in ("libx265", "libx264"):
        return [
            FFMPEG, "-y", "-i", path,
            "-c:v", encoder_key, "-preset", "slow", "-crf", str(quality_value),
            *_vf_args(vf),
            "-c:a", "aac", "-b:a", f"{audio_kbps}k",
            out_path,
        ]
    elif encoder_key in ("hevc_nvenc", "av1_nvenc"):
        return [
            FFMPEG, "-y", "-i", path,
            "-c:v", encoder_key, "-preset", "p7", "-rc", "vbr",
            "-cq", str(quality_value), "-b:v", "0",
            *_vf_args(vf),
            "-c:a", "aac", "-b:a", f"{audio_kbps}k",
            out_path,
        ]
    raise ValueError(f"ترميز غير معروف: {encoder_key}")


def compress_quality(path, out_path, encoder_key, level, manual_value, log, audio_kbps=AUDIO_KBPS_DEFAULT,
                      denoise_level="off"):
    value = manual_value if manual_value is not None else QUALITY_PRESETS[encoder_key][level]
    vf = DENOISE_FILTERS.get(denoise_level)
    log(f"  الترميز بواسطة {encoder_key} بجودة ثابتة (قيمة {value})"
        f"{' مع تنعيم ضوضاء' if vf else ''}...")
    run_checked(build_quality_cmd(path, out_path, encoder_key, value, audio_kbps, vf), log)


def run_checked(cmd, log):
    log("  > " + " ".join(cmd))
    proc = subprocess.run(cmd, capture_output=True, text=True)
    if proc.returncode != 0:
        raise subprocess.CalledProcessError(proc.returncode, cmd,
                                             output=proc.stdout, stderr=proc.stderr)


# ---------------------------------------------------------------------------
# طريقة "تصغير بنسبة ثابتة لكل فيديو (ذكي)" - الهدف: أي فيديو يدخل البرنامج
# ينزل حجمه بنسبة محددة (مثلاً 80%) بالنسبة لحجمه هو، لكن بأولوية مطلقة
# للجودة العالية:
#   ١. نختبر على عيّنة قصيرة كم نسبة تصغير بتعطي "جودة عالية تلقائياً"
#      (CRF/CQ) - هذا دائماً أفضل خيار للجودة لأنه ما يفرض بترتيت معيّن.
#   ٢. لو هذه النسبة وحدها كافية أو أكثر من المطلوب -> نكتفي بها (أعلى جودة
#      ممكنة، وبدون أي تضييق إضافي غير ضروري على الحجم).
#   ٣. لو غير كافية (محتوى صعب الضغط) -> نحول لوضع "حجم مستهدف" بحجم يساوي
#      النسبة المطلوبة من الحجم الأصلي، لكن بدون النزول عن الحد الأدنى
#      المعقول لعدد البتات (حسب الدقة) حتى لو هذا يعني عدم الوصول للنسبة
#      كاملة - نفضّل جودة مقبولة دائماً على رقم نسبة دقيق.
# ---------------------------------------------------------------------------

def compress_smart_percentage(path, out_path, percent_reduction, encoder_key, log,
                               quality_level="balanced", manual_value=None,
                               audio_kbps=AUDIO_KBPS_DEFAULT, denoise_level="off"):
    before_mb = os.path.getsize(path) / (1024 * 1024)
    duration = get_duration_seconds(path)

    log(f"  (تصغير ذكي) اختبار عيّنة بجودة عالية تلقائياً أولاً لمعرفة هل تكفي "
        f"لتحقيق تصغير {percent_reduction:.0f}%...")
    est = estimate_one(path, "quality", encoder_key, log, quality_level=quality_level,
                        manual_value=manual_value, denoise_level=denoise_level, sample_len=6.0)

    predicted_pct = None
    if est and est["estimated_mb"] and before_mb:
        predicted_pct = (1 - est["estimated_mb"] / before_mb) * 100

    if predicted_pct is not None and predicted_pct >= percent_reduction:
        log(f"  الجودة العالية التلقائية وحدها كافية (تصغير متوقع ~{predicted_pct:.0f}% "
            f">= {percent_reduction:.0f}% المطلوب) - سيُستخدم وضع الجودة مباشرة بدون أي "
            f"تضييق إضافي على الحجم.")
        compress_quality(path, out_path, encoder_key, quality_level, manual_value, log,
                          audio_kbps, denoise_level)
        return

    if predicted_pct is not None:
        log(f"  الجودة العالية التلقائية وحدها تعطي ~{predicted_pct:.0f}% فقط (أقل من "
            f"{percent_reduction:.0f}% المطلوب) - سنضيّق الحجم أكثر، بحذر على الجودة.")
    else:
        log("  تعذّر اختبار العيّنة، سنكمل مباشرة بوضع الحجم المستهدف.")

    target_mb = before_mb * (1 - percent_reduction / 100.0)
    four_k = is_4k_or_above(path)
    floor = quality_floor_kbps(four_k)
    needed_kbps = compute_video_kbps(target_mb, duration, audio_kbps) if duration > 0 else floor

    if needed_kbps < floor:
        # النسبة المطلوبة تحتاج بترتيت أقل من الحد الأدنى المعقول لهذه الدقة.
        # نكتفي بأكبر تصغير ممكن عند الحد الأدنى بالضبط، بدل عيوب ضغط واضحة.
        safe_target_mb = (floor + audio_kbps) * duration / (8000 * SAFETY_MARGIN) if duration > 0 else target_mb
        achieved_pct = (1 - safe_target_mb / before_mb) * 100 if before_mb else percent_reduction
        log(f"  تحذير: تصغير {percent_reduction:.0f}% كامل لهذا الفيديو كان سيعطي عيوب "
            f"ضغط واضحة بهذه الدقة. سيتم الاكتفاء بأكبر تصغير ممكن مع جودة مقبولة "
            f"(~{achieved_pct:.0f}% تقريباً) بدل الوصول للنسبة المطلوبة كاملة.")
        target_mb = safe_target_mb

    compress_target_size(path, out_path, target_mb, encoder_key, log, audio_kbps, denoise_level)


def unique_output_path(out_path):
    """لو في ملف بنفس الاسم أصلاً (ممكن لما نجمع فيديوهات من مجلدات مختلفة
    بنفس الاسم بمجلد حفظ واحد)، نضيف رقم بدل ما نكتب فوق ملف موجود."""
    if not os.path.exists(out_path):
        return out_path
    base, ext = os.path.splitext(out_path)
    i = 2
    while os.path.exists(f"{base}_{i}{ext}"):
        i += 1
    return f"{base}_{i}{ext}"


def compress_one(path, mode, encoder_key, log, target_mb=None, quality_level=None,
                  manual_value=None, audio_kbps=AUDIO_KBPS_DEFAULT, denoise_level="off",
                  output_dir=None, smart_percent=None):
    """ينفذ الضغط لملف واحد حسب الطريقة المختارة، ويرجع مسار الملف الناتج.
    لو output_dir محدد يُحفظ الناتج هناك، وإلا بجانب الفيديو الأصلي (كالسابق)."""
    if output_dir:
        base_name = os.path.splitext(os.path.basename(path))[0] + "_compressed.mp4"
        out_path = unique_output_path(os.path.join(output_dir, base_name))
    else:
        out_path = os.path.splitext(path)[0] + "_compressed.mp4"
    if mode == "quality":
        compress_quality(path, out_path, encoder_key, quality_level, manual_value, log, audio_kbps,
                          denoise_level)
    elif mode == "size":
        compress_target_size(path, out_path, target_mb, encoder_key, log, audio_kbps, denoise_level)
    elif mode == "smart_percent":
        compress_smart_percentage(path, out_path, smart_percent, encoder_key, log,
                                   quality_level=quality_level, manual_value=manual_value,
                                   audio_kbps=audio_kbps, denoise_level=denoise_level)
    else:
        raise ValueError(f"طريقة غير معروفة: {mode}")
    return out_path


# ---------------------------------------------------------------------------
# تقدير سريع للحجم والجودة المتوقعة - بدون ضغط الفيديو كامل
# ---------------------------------------------------------------------------
# الفكرة: نأخذ عيّنتين قصيرتين (بضع ثوانٍ) من أماكن مختلفة بالفيديو، نشفّرهما
# بنفس الإعدادات بالضبط اللي رح تُستخدم على الفيديو كامل، ونقيس SSIM (مقياس
# تشابه بصري معتمد وشائع الاستخدام) بين كل عيّنة والأصل. من حجم العيّنات
# المشفّرة نستنتج البتريت المتوقع وبالتالي الحجم النهائي التقريبي، ومن SSIM
# نعطي حكماً على الجودة المتوقعة. هذا تقدير مبني على اختبار فعلي (مش تخمين)،
# لكنه يبقى تقديراً: لو باقي الفيديو مختلف كثير عن العيّنات (مثلاً مشهد واحد
# هادئ ومشهد ثاني فيه حركة عنيفة) ممكن الرقم الفعلي يختلف شوي.

def build_x26x_singlepass_cmd(path, out_path, codec, video_kbps, audio_kbps, vf=None):
    """نسخة بتمريرة واحدة (أسرع) تُستخدم فقط لتقدير الحجم/المعاينة على عيّنة صغيرة.
    نستخدم نفس preset "slow" المستخدم بالترميز الحقيقي (2-pass) حتى يطابق
    التقدير والمعاينة ما سينتج فعلياً عند ضغط الفيديو كامل."""
    v_bitrate = f"{int(video_kbps)}k"
    return [
        FFMPEG, "-y", "-i", path, "-c:v", codec, "-preset", "slow", "-b:v", v_bitrate,
        *_vf_args(vf), "-c:a", "aac", "-b:a", f"{audio_kbps}k", out_path,
    ]


def extract_sample(path, start_seconds, duration_seconds, out_path, log):
    cmd = [FFMPEG, "-y", "-ss", f"{start_seconds:.2f}", "-i", path,
           "-t", f"{duration_seconds:.2f}", "-c", "copy", out_path]
    run_checked(cmd, log)


def measure_ssim(reference_path, encoded_path, log):
    cmd = [FFMPEG, "-i", encoded_path, "-i", reference_path, "-lavfi", "ssim", "-f", "null", "-"]
    proc = subprocess.run(cmd, capture_output=True, text=True)
    m = re.search(r"All:([0-9.]+)", proc.stderr)
    if m:
        return float(m.group(1))
    log("  تعذر قياس SSIM لهذه العيّنة.")
    return None


def ssim_to_verdict(ssim):
    if ssim is None:
        return "غير معروفة (تعذر القياس على هذه العيّنة)"
    if ssim >= 0.99:
        return f"ممتازة جداً - عملياً لا فرق عن الأصل (SSIM {ssim:.3f})"
    if ssim >= 0.97:
        return f"ممتازة - فرق غير ملحوظ تقريباً (SSIM {ssim:.3f})"
    if ssim >= 0.95:
        return f"جيدة جداً - فرق طفيف جداً عند التدقيق (SSIM {ssim:.3f})"
    if ssim >= 0.90:
        return f"جيدة - فرق ملحوظ بالتفاصيل الدقيقة (SSIM {ssim:.3f})"
    return f"ضعيفة - عيوب ضغط واضحة متوقعة (SSIM {ssim:.3f})"


def pick_sample_starts(duration, sample_len=6.0):
    if duration <= sample_len * 1.8:
        return [max(0.0, duration / 2 - sample_len / 2)]
    return [0.3 * duration, 0.7 * duration]


def estimate_one(path, mode, encoder_key, log, target_mb=None, quality_level=None,
                  manual_value=None, denoise_level="off", audio_kbps=AUDIO_KBPS_DEFAULT,
                  sample_len=6.0):
    """يرجع dict فيه الحجم التقديري ومستوى الجودة المتوقع، أو None لو فشل."""
    duration = get_duration_seconds(path)
    vf = DENOISE_FILTERS.get(denoise_level)
    starts = pick_sample_starts(duration, sample_len)

    target_video_kbps = None
    if mode == "size":
        target_video_kbps = max(compute_video_kbps(target_mb, duration, audio_kbps), 150)
    quality_value = None
    if mode == "quality":
        quality_value = manual_value if manual_value is not None else QUALITY_PRESETS[encoder_key][quality_level]

    sample_kbps_list, ssim_list, tmp_files = [], [], []
    try:
        for i, start in enumerate(starts):
            raw = path + f".__sample_raw_{i}.mp4"
            enc = path + f".__sample_enc_{i}.mp4"
            tmp_files += [raw, enc]
            try:
                extract_sample(path, start, sample_len, raw, log)
            except subprocess.CalledProcessError:
                continue
            actual_dur = get_duration_seconds(raw)
            if actual_dur <= 0:
                continue

            if mode == "quality":
                cmd = build_quality_cmd(raw, enc, encoder_key, quality_value, audio_kbps, vf)
            elif encoder_key in ("av1_nvenc", "hevc_nvenc"):
                cmd = build_nvenc_bitrate_cmd(raw, enc, encoder_key, target_video_kbps, audio_kbps, vf)
            else:
                cmd = build_x26x_singlepass_cmd(raw, enc, encoder_key, target_video_kbps, audio_kbps, vf)
            run_checked(cmd, log)

            enc_size = os.path.getsize(enc)
            sample_kbps_list.append((enc_size * 8 / 1000) / actual_dur)
            score = measure_ssim(raw, enc, log)
            if score is not None:
                ssim_list.append(score)
    finally:
        for f in tmp_files:
            try:
                os.remove(f)
            except OSError:
                pass

    if not sample_kbps_list:
        return None

    avg_kbps = sum(sample_kbps_list) / len(sample_kbps_list)
    estimated_mb = avg_kbps * duration / 8000
    avg_ssim = sum(ssim_list) / len(ssim_list) if ssim_list else None
    return {"estimated_mb": estimated_mb, "ssim": avg_ssim, "verdict": ssim_to_verdict(avg_ssim)}


# ---------------------------------------------------------------------------
# معاينة بصرية للجودة: صورة حقيقية (فريم واحد) قبل/بعد الضغط، بدون انتظار
# ضغط الفيديو كامل. تُستخدم على عيّنة قصيرة فقط (مثل التقدير السريع أعلاه)
# لكن بدل رقم SSIM وحده، تعرض الفريم فعلياً بالعين.
# ---------------------------------------------------------------------------

def extract_frame_png(path, timestamp_seconds, out_path, log, width=640):
    """يسحب فريم واحد من الفيديو عند ثانية معيّنة ويحفظه كصورة PNG."""
    cmd = [FFMPEG, "-y", "-ss", f"{timestamp_seconds:.2f}", "-i", path,
           "-frames:v", "1", "-vf", f"scale={width}:-2", out_path]
    run_checked(cmd, log)


def preview_quality(path, mode, encoder_key, log, target_mb=None, quality_level=None,
                     manual_value=None, denoise_level="off", audio_kbps=AUDIO_KBPS_DEFAULT,
                     sample_len=3.0, frame_width=640):
    """
    معاينة سريعة لجودة الضغط على فيديو واحد: يسحب عيّنة قصيرة من منتصف الفيديو
    تقريباً، يضغطها بنفس الإعدادات المطلوبة، ثم يطلع صورتين (قبل/بعد) لنفس
    اللحظة بالضبط حتى تتم المقارنة بالعين مباشرة، بالإضافة لتقدير الحجم
    النهائي ودرجة SSIM المحسوبة على نفس العيّنة.

    يرجع dict: before_png, after_png, estimated_mb, ssim, verdict, tmp_dir
    (المجلد المؤقت الذي يحوي الصورتين - على المستدعي حذفه بعد عرضهما).
    """
    duration = get_duration_seconds(path)
    if duration <= 0:
        raise RuntimeError("تعذر قراءة مدة الفيديو")

    eff_sample_len = min(sample_len, duration) if duration < sample_len else sample_len
    start = max(0.0, min(duration * 0.4, max(0.0, duration - eff_sample_len)))
    vf = DENOISE_FILTERS.get(denoise_level)

    tmp_dir = tempfile.mkdtemp(prefix="watar_preview_")
    raw = os.path.join(tmp_dir, "raw.mp4")
    enc = os.path.join(tmp_dir, "enc.mp4")
    before_png = os.path.join(tmp_dir, "before.png")
    after_png = os.path.join(tmp_dir, "after.png")

    try:
        extract_sample(path, start, eff_sample_len, raw, log)
        actual_dur = get_duration_seconds(raw)
        if actual_dur <= 0:
            raise RuntimeError("تعذّر سحب عيّنة من هذا الفيديو للمعاينة")

        if mode == "size":
            target_video_kbps = max(compute_video_kbps(target_mb, duration, audio_kbps), 150)
            if encoder_key in ("av1_nvenc", "hevc_nvenc"):
                cmd = build_nvenc_bitrate_cmd(raw, enc, encoder_key, target_video_kbps, audio_kbps, vf)
            else:
                cmd = build_x26x_singlepass_cmd(raw, enc, encoder_key, target_video_kbps, audio_kbps, vf)
        else:
            quality_value = manual_value if manual_value is not None else QUALITY_PRESETS[encoder_key][quality_level]
            cmd = build_quality_cmd(raw, enc, encoder_key, quality_value, audio_kbps, vf)
        run_checked(cmd, log)

        frame_t = max(0.0, min(actual_dur / 2.0, actual_dur - 0.05))
        extract_frame_png(raw, frame_t, before_png, log, frame_width)
        extract_frame_png(enc, frame_t, after_png, log, frame_width)

        enc_size = os.path.getsize(enc)
        sample_kbps = (enc_size * 8 / 1000) / actual_dur
        estimated_mb = sample_kbps * duration / 8000
        ssim = measure_ssim(raw, enc, log)

        return {
            "before_png": before_png, "after_png": after_png,
            "estimated_mb": estimated_mb, "ssim": ssim,
            "verdict": ssim_to_verdict(ssim), "tmp_dir": tmp_dir,
        }
    except Exception:
        shutil.rmtree(tmp_dir, ignore_errors=True)
        raise
    finally:
        for f in (raw, enc):
            try:
                os.remove(f)
            except OSError:
                pass


